B.aRP=new A.a("\u0648\u0647\u0643\u0630\u0627 \u0628\u0627\u064a\u0639 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0646\u0635\u0631\u0629 \u0648\u0627\u0644\u062d\u0631\u0628\u060c \u0644\u0630\u0644\u0643 \u0633\u0645\u0627\u0647\u0627 \u0639\u0628\u0627\u062f\u0629 \u0628\u0646 \u0627\u0644\u0635\u0627\u0645\u062a \u0628\u064a\u0639\u0629 \u0627\u0644\u062d\u0631\u0628 \u060c \u0623\u0645\u0627 \u0631\u0648\u0627\u064a\u0629 \u0627\u0644\u0635\u062d\u0627\u0628\u064a \u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a\u060c \u0648\u0647\u0648 \u0623\u062d\u062f \u0627\u0644\u0645\u0628\u0627\u064a\u0639\u064a\u0646 \u0641\u064a \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629\u060c \u0641\u0641\u064a\u0647\u0627 \u062a\u0641\u0627\u0635\u064a\u0644 \u0645\u0647\u0645\u0629 \u0642\u0627\u0644: \u062e\u0631\u062c\u0646\u0627 \u0641\u064a \u062d\u062c\u0627\u062c \u0642\u0648\u0645\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0642\u062f \u0635\u0644\u064a\u0646\u0627 \u0648\u0641\u0642\u0647\u0646\u0627.. \u062b\u0645 \u062e\u0631\u062c\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u062c\u060c \u0648\u0648\u0627\u0639\u062f\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0639\u0642\u0628\u0629 \u0645\u0646 \u0623\u0648\u0633\u0637 \u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u0634\u0631\u064a\u0642... \u0648\u0643\u0646\u0627 \u0646\u0643\u062a\u0645 \u0645\u0646 \u0645\u0639\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u0645\u0631\u0646\u0627.",null)
B.aRn=new A.a("\u0641\u0646\u0645\u0646\u0627 \u062a\u0644\u0643 \u0627\u0644\u0644\u064a\u0644\u0629 \u0645\u0639 \u0642\u0648\u0645\u0646\u0627 \u0641\u064a \u0631\u062d\u0627\u0644\u0646\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0645\u0636\u0649 \u062b\u0644\u062b \u0627\u0644\u0644\u064a\u0644 \u062e\u0631\u062c\u0646\u0627 \u0645\u0646 \u0631\u062d\u0627\u0644\u0646\u0627 \u0644\u0645\u064a\u0639\u0627\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0646\u062a\u0633\u0644\u0644 \u062a\u0633\u0644\u0644 \u0627\u0644\u0642\u0637\u0627 \u0645\u0633\u062a\u062e\u0641\u064a\u0646\u060c \u062d\u062a\u0649 \u0627\u062c\u062a\u0645\u0639\u0646\u0627 \u0641\u064a \u0627\u0644\u0634\u0639\u0628 \u0639\u0646\u062f \u0627\u0644\u0639\u0642\u0628\u0629\u060c \u0648\u0646\u062d\u0646 \u062b\u0644\u0627\u062b\u0629 \u0648\u0633\u0628\u0639\u0648\u0646 \u0631\u062c\u0644\u0627\u064b \u0648\u0645\u0639\u0646\u0627 \u0627\u0645\u0631\u0623\u062a\u0627\u0646 \u0645\u0646 \u0646\u0633\u0627\u0626\u0646\u0627\u060c \u0646\u064f\u0633\u064a\u0628\u0629 \u0628\u0646\u062a \u0643\u0639\u0628\u060c \u0648\u0623\u0633\u0645\u0627\u0621 \u0628\u0646\u062a \u0639\u0645\u0631\u0648.",null)
B.b6M=new A.a("\u0641\u0627\u062c\u062a\u0645\u0639\u0646\u0627 \u0641\u064a \u0627\u0644\u0634\u0639\u0628 \u0646\u0646\u062a\u0638\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u062a\u0649 \u062c\u0627\u0621\u0646\u0627 \u0648\u0645\u0639\u0647 \u0627\u0644\u0639\u0628\u0627\u0633 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628\u060c \u0648\u0647\u0648 \u064a\u0648\u0645\u0626\u0630 \u0639\u0644\u0649 \u062f\u064a\u0646 \u0642\u0648\u0645\u0647\u060c \u0625\u0644\u0627 \u0623\u0646\u0647 \u0623\u062d\u0628 \u0623\u0646 \u064a\u062d\u0636\u0631 \u0623\u0645\u0631 \u0627\u0628\u0646 \u0623\u062e\u064a\u0647\u060c \u0648\u064a\u062a\u0648\u062b\u0642 \u0644\u0647\u060c \u0641\u0644\u0645\u0627 \u062c\u0644\u0633 \u0643\u0627\u0646 \u0623\u0648\u0644 \u0645\u062a\u0643\u0644\u0645 \u0627\u0644\u0639\u0628\u0627\u0633 \u0628\u0646 \u0639\u0628\u062f \u0627\u0644\u0645\u0637\u0644\u0628: \u0641\u0628\u064a\u0646 \u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \u0641\u064a \u0645\u0646\u0639\u0629 \u0645\u0646 \u0642\u0648\u0645\u0647 \u0628\u0646\u064a \u0647\u0627\u0634\u0645\u060c \u0648\u0644\u0643\u0646\u0647 \u064a\u0631\u064a\u062f \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0644\u0630\u0644\u0643 \u0641\u0625\u0646 \u0627\u0644\u0639\u0628\u0627\u0633 \u064a\u0631\u064a\u062f \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0644\u0647 \u0648\u0625\u0644\u0627 \u0641\u0644\u064a\u062f\u0639\u0648\u0647 \u0641\u0637\u0644\u0628 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0623\u0646 \u064a\u062a\u0643\u0644\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u0623\u062e\u0630 \u0644\u0646\u0641\u0633\u0647 \u0648\u0644\u0631\u0628\u0647 \u0645\u0627 \u064a\u062d\u0628 \u0645\u0646 \u0627\u0644\u0634\u0631\u0648\u0637.",null)
