B.aZN=new A.a("\u0641\u0642\u0631\u0631\u0648\u0627 \u0628\u0639\u062f \u0630\u0644\u0643 \u0625\u0631\u0633\u0627\u0644\u0647 \u0645\u0639 \u0639\u0642\u0628\u0629 \u0628\u0646 \u0623\u0628\u064a \u0645\u0639\u064a\u0637\u060c \u0625\u0644\u0649 \u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0644\u0645\u0639\u0631\u0641\u0629 \u062d\u0642\u064a\u0642\u0629 \u0647\u0630\u0647 \u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0644\u0627 \u0644\u0643\u064a \u064a\u062a\u0628\u0639\u0648\u0647\u0627\u060c \u0648\u0644\u0643\u0646 \u0644\u0625\u062f\u0631\u0627\u0643\u0647\u0645 \u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0642\u062f \u064a\u0645\u062f\u0648\u0646\u0647\u0645 \u0628\u0623\u0634\u064a\u0627\u0621 \u062a\u0638\u0647\u0631 \u0639\u062c\u0632 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0644\u0645\u0639\u0631\u0641\u0629 \u0632\u0639\u0645\u0627\u0621 \u0645\u0643\u0629 \u0628\u062d\u0642\u062f \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0645\u0646\u0635\u0628 \u0639\u0644\u0649 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627 \u0648\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062d\u0642 \u0623\u064a\u0646\u0645\u0627 \u0643\u0627\u0646\u0648\u0627\u060c \u0643\u0627\u0646\u062a \u0628\u0639\u062b\u0629 \u0627\u0644\u0645\u0635\u0637\u0641\u0649 \ufdfa \u0635\u062f\u0645\u0629 \u0642\u0648\u064a\u0629 \u0644\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0630\u0644\u0643 \u0644\u0623\u0646\u0647\u0645 \u0639\u0627\u0634\u0648\u0627 \u0641\u064a \u062c\u0632\u064a\u0631\u0629 \u0627\u0644\u0639\u0631\u0628 \u0639\u0644\u0649 \u062d\u0644\u0645 \u062a\u0648\u0627\u0631\u062b\u0648\u0647 \u0637\u0648\u0627\u0644 \u0627\u0644\u0633\u0646\u064a\u0646 \u0627\u0644\u0645\u0627\u0636\u064a\u0629\u060c \u0648\u0647\u0648 \u0623\u0646\u0647 \u0633\u064a\u064f\u0628\u0639\u062b \u0646\u0628\u064a \u0645\u062e\u0644\u0635 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0632\u0645\u0627\u0646 \u0648\u0627\u0644\u0645\u0643\u0627\u0646\u060c \u0641\u0631\u062c\u0648\u0627 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u0646\u0647\u0645\u060c \u0622\u0645\u0644\u064a\u0646 \u0623\u0646 \u064a\u062e\u0644\u0635\u0647\u0645 \u0645\u0646 \u0627\u0644\u0641\u0631\u0642\u0629 \u0648\u0627\u0644\u0634\u062a\u0627\u062a \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u0648\u0627 \u0641\u064a\u0647.",null)
B.aK4=new A.a("\u0643\u0627\u0646 \u0627\u0644\u062a\u0642\u0627\u0631\u0628 \u0628\u064a\u0646 \u0645\u0639\u0633\u0643\u0631 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0634\u0631\u0643 \u0645\u0639 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u064a\u0646\u0633\u062c\u0645 \u0645\u0639 \u0623\u0647\u062f\u0627\u0641\u0647\u0645 \u0627\u0644\u0645\u0634\u062a\u0631\u0643\u0629 \u0644\u0644\u0642\u0636\u0627\u0621 \u0639\u0644\u0649 \u062f\u0639\u0648\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0644\u0630\u0644\u0643 \u0632\u0648\u062f\u0648\u0627 \u0627\u0644\u0648\u0641\u062f \u0627\u0644\u0645\u0643\u064a \u0628\u0628\u0639\u0636 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0645\u062d\u0627\u0648\u0644\u0629 \u0644\u062a\u0639\u062c\u064a\u0632 \u0627\u0644\u0646\u0628\u064a \ufdfa",null)
B.aWL=new A.a("\u0639\u0646 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644: \u0628\u0639\u062b\u062a \u0642\u0631\u064a\u0634 \u0627\u0644\u0646\u0636\u0631 \u0628\u0646 \u0627\u0644\u062d\u0627\u0631\u062b \u0648\u0639\u0642\u0628\u0629 \u0628\u0646 \u0623\u0628\u064a \u0645\u0639\u064a\u0637 \u0625\u0644\u0649 \u0623\u062d\u0628\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0641\u0642\u0627\u0644\u0648\u0627 \u0644\u0647\u0645: \u0633\u0644\u0648\u0647\u0645 \u0639\u0646 \u0645\u062d\u0645\u062f\u060c \u0648\u0635\u0641\u0648\u0627 \u0644\u0647\u0645 \u0635\u0641\u062a\u0647\u060c \u0648\u0623\u062e\u0628\u0631\u0648\u0647\u0645 \u0628\u0642\u0648\u0644\u0647\u060c \u0641\u0625\u0646\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0623\u0648\u0644\u060c \u0648\u0639\u0646\u062f\u0647\u0645 \u0639\u0644\u0645 \u0645\u0627 \u0644\u064a\u0633 \u0639\u0646\u062f\u0646\u0627 \u0645\u0646 \u0639\u0644\u0645 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u060c \u0641\u062e\u0631\u062c\u0627 \u062d\u062a\u0649 \u0642\u062f\u0645\u0627 \u0627\u0644\u0645\u062f\u0646\u064a\u0629\u060c \u0641\u0633\u0623\u0644\u0627 \u0623\u062d\u0628\u0627\u0631 \u064a\u0647\u0648\u062f \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0648\u0635\u0641\u0627 \u0644\u0647\u0645 \u0623\u0645\u0631\u0647 \u0648\u0628\u0639\u0636 \u0642\u0648\u0644\u0647\u060c \u0648\u0642\u0627\u0644\u0627: \u0625\u0646\u0643\u0645 \u0623\u0647\u0644 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0642\u062f \u062c\u0626\u0646\u0627\u0643\u0645 \u0644\u062a\u062e\u0628\u0631\u0648\u0646\u0627 \u0639\u0646 \u0635\u0627\u062d\u0628\u0646\u0627 \u0647\u0630\u0627\u060c \u0642\u0627\u0644: \u0641\u0642\u0627\u0644\u062a \u0644\u0647\u0645 \u0623\u062d\u0628\u0627\u0631 \u064a\u0647\u0648\u062f: \u0633\u0644\u0648\u0647 \u0639\u0646 \u062b\u0644\u0627\u062b \u0646\u0623\u0645\u0631\u0643\u0645 \u0628\u0647\u0646\u060c \u0641\u0625\u0646 \u0623\u062e\u0628\u0631\u0643\u0645 \u0628\u0647\u0646 \u0641\u0647\u0648 \u0646\u0628\u064a \u0645\u0631\u0633\u0644\u060c \u0648\u0625\u0646 \u0644\u0645 \u064a\u0641\u0639\u0644 \u0641\u0627\u0644\u0631\u062c\u0644 \u0645\u064f\u062a\u064e\u0642\u0648\u0644   -\u0627\u0633\u0645 \u0627\u0644\u0645\u0641\u0639\u0648\u0644 \u0645\u0646 \u062a\u064e\u0642\u0648\u0651\u064e\u0644\u064e-  \u060c \u0641\u0631\u0648\u0627 \u0641\u064a\u0647 \u0631\u0623\u064a\u0643\u0645: \u0633\u0644\u0648\u0647 \u0639\u0646 \u0641\u062a\u064a\u0629 \u0630\u0647\u0628\u0648\u0627 \u0641\u064a \u0627\u0644\u062f\u0647\u0631 \u0627\u0644\u0623\u0648\u0644 \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u0645\u0631\u0647\u0645\u061f \u0641\u0625\u0646\u0647 \u0642\u062f \u0643\u0627\u0646 \u0644\u0647\u0645 \u062d\u062f\u064a\u062b \u0639\u062c\u064a\u0628\u060c \u0648\u0633\u0644\u0648\u0647 \u0639\u0646 \u0631\u062c\u0644 \u0637\u0648\u0627\u0641 \u0628\u0644\u063a \u0645\u0634\u0627\u0631\u0642 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u063a\u0627\u0631\u0628\u0647\u0627 \u0645\u0627 \u0643\u0627\u0646 \u0646\u0628\u0624\u0647\u061f \u0648\u0633\u0644\u0648\u0647 \u0639\u0646 \u0627\u0644\u0631\u0648\u062d\u060c \u0645\u0627 \u0647\u0648\u061f \u0641\u0625\u0646 \u0623\u062e\u0628\u0631\u0643\u0645 \u0628\u0630\u0644\u0643 \u0641\u0625\u0646\u0647 \u0646\u0628\u064a \u0641\u0627\u062a\u0628\u0639\u0648\u0647\u060c \u0648\u0625\u0646 \u0647\u0648 \u0644\u0645 \u064a\u062e\u0628\u0631\u0643\u0645 \u0641\u0647\u0648 \u0631\u062c\u0644 \u0645\u062a\u0642\u0648\u0644 \u0641\u0627\u0635\u0646\u0639\u0648\u0627 \u0641\u064a \u0623\u0645\u0631\u0647 \u0645\u0627 \u0628\u062f\u0627 \u0644\u0643\u0645.",null)
B.bb2=new A.a("\u0641\u0623\u0642\u0628\u0644 \u0627\u0644\u0646\u0636\u0631 \u0648\u0639\u0642\u0628\u0629 \u062d\u062a\u0649 \u0642\u062f\u0645\u0627 \u0645\u0643\u0629 \u0639\u0644\u0649 \u0642\u0631\u064a\u0634 \u0641\u0642\u0627\u0644\u0627: \u064a\u0627 \u0645\u0639\u0634\u0631 \u0642\u0631\u064a\u0634\u060c \u0642\u062f \u062c\u0626\u0646\u0627\u0643\u0645 \u0628\u0641\u0635\u0644 \u0645\u0627 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646 \u0645\u062d\u0645\u062f\u060c \u0642\u062f \u0623\u0645\u0631\u0646\u0627 \u0623\u062d\u0628\u0627\u0631 \u064a\u0647\u0648\u062f \u0623\u0646 \u0646\u0633\u0623\u0644\u0647 \u0639\u0646 \u0623\u0645\u0648\u0631\u060c \u0641\u0623\u062e\u0628\u0631\u0648\u0647\u0645 \u0628\u0647\u0627\u060c \u0641\u062c\u0627\u0621\u0648\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644\u0648\u0627: \u064a\u0627 \u0645\u062d\u0645\u062f\u060c \u0623\u062e\u0628\u0631\u0646\u0627\u060c \u0641\u0633\u0623\u0644\u0648\u0647 \u0639\u0645\u0627 \u0623\u0645\u0631\u0648\u0647\u0645 \u0628\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0623\u062e\u0628\u0631\u0643\u0645 \u063a\u062f\u064b\u0627 \u0628\u0645\u0627 \u0633\u0623\u0644\u062a\u0645 \u0639\u0646\u0647\u060c \u0648\u0644\u0645 \u064a\u0633\u062a\u062b\u0646 -\u0623\u064a \u0644\u0645 \u064a\u0642\u0644 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647- \u060c \u0641\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0639\u0646\u0647\u060c \u0641\u0645\u0643\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062e\u0645\u0633 \u0639\u0634\u0631\u0629 \u0644\u064a\u0644\u0629 \u0644\u0627 \u064a\u062d\u062f\u062b \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647 \u0641\u064a \u0630\u0644\u0643 \u0648\u062d\u064a\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u0623\u062a\u064a\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u062d\u062a\u0649 \u0623\u0631\u062c\u0641 \u0623\u0647\u0644 \u0645\u0643\u0629 \u0648\u0642\u0627\u0644\u0648\u0627: \u0648\u0639\u062f\u0646\u0627 \u0645\u062d\u0645\u062f\u064b\u0627 \u063a\u062f\u064b\u0627 \u0648\u0627\u0644\u064a\u0648\u0645 \u062e\u0645\u0633 \u0639\u0634\u0631\u0629\u060c \u0642\u062f \u0623\u0635\u0628\u062d\u0646\u0627 \u0641\u064a\u0647\u0627 \u0644\u0627 \u064a\u062e\u0628\u0631\u0646\u0627 \u0628\u0634\u064a\u0621 \u0645\u0645\u0627 \u0633\u0623\u0644\u0646\u0627\u0647 \u0639\u0646\u0647\u060c \u0648\u062d\u062a\u0649 \u0623\u062d\u0632\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u064f\u0643\u0652\u062b\u064f \u0627\u0644\u0648\u062d\u064a \u0639\u0646\u0647\u060c \u0648\u0634\u0642 \u0639\u0644\u064a\u0647 \u0645\u0627 \u064a\u062a\u0643\u0644\u0645 \u0628\u0647 \u0623\u0647\u0644 \u0645\u0643\u0629\u060c \u062b\u0645 \u062c\u0627\u0621\u0647 \u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0628\u0633\u0648\u0631\u0629 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0643\u0647\u0641 \u0641\u064a\u0647\u0627 \u0645\u0639\u0627\u062a\u0628\u062a\u0647 \u0625\u064a\u0627\u0647 \u0639\u0644\u0649 \u062d\u0632\u0646\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u062e\u0628\u0631 \u0645\u0627 \u0633\u0623\u0644\u0648\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0641\u062a\u064a\u0629 \u0648\u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0637\u0648\u0627\u0641\u060c \u0648\u0642\u0648\u0644 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644: \u0648\u064e\u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u0650 \u0642\u064f\u0644\u0650 \u0627\u0644\u0631\u0651\u064f\u0648\u062d\u064f \u0645\u0650\u0646\u0652 \u0623\u064e\u0645\u0652\u0631\u0650 \u0631\u064e\u0628\u0651\u0650\u064a \u0648\u064e\u0645\u064e\u0627 \u0623\u064f\u0648\u062a\u0650\u064a\u062a\u064f\u0645 \u0645\u0651\u0650\u0646 \u0627\u0644\u0652\u0639\u0650\u0644\u0652\u0645\u0650 \u0625\u0650\u0644\u0627\u0651\u064e \u0642\u064e\u0644\u0650\u064a\u0644\u0627\u064b.",null)
