B.b03=new A.a("\u0642\u0627\u0644 \u0623\u0628\u0648 \u0643\u0628\u0634\u0629 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0644\u0645\u0627 \u0643\u0627\u0646 \u0641\u064a \u063a\u0632\u0648\u0629 \u062a\u0628\u0648\u0643 \u062a\u0633\u0627\u0631\u0639 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u062d\u062c\u0631 \u064a\u062f\u062e\u0644\u0648\u0646 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0628\u0644\u063a \u0630\u0644\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0646\u0627\u062f\u0649 \u0641\u064a \u0627\u0644\u0646\u0627\u0633: \u0627\u0644\u0635\u0644\u0627\u0629 \u062c\u0627\u0645\u0639\u0629 \u0642\u0627\u0644: \u0641\u0623\u062a\u064a\u062a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0647\u0648 \u0645\u0645\u0633\u0643 \u0628\u0639\u064a\u0631\u0647 \u0648\u0647\u0648 \u064a\u0642\u0648\u0644: \u0645\u0627\u062a\u062f\u062e\u0644\u0648\u0646 \u0639\u0644\u0649 \u0642\u0648\u0645 \u063a\u0636\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0641\u0646\u0627\u062f\u0627\u0647 \u0631\u062c\u0644 \u0645\u0646\u0647\u0645: \u0646\u0639\u062c\u0628 \u0645\u0646\u0647\u0645 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0642\u0627\u0644: \u0623\u0641\u0644\u0627 \u0623\u0646\u0630\u0631\u0643\u0645 \u0628\u0623\u0639\u062c\u0628 \u0645\u0646 \u0630\u0644\u0643\u061f \u0631\u062c\u0644 \u0645\u0646 \u0623\u0646\u0641\u0633\u0643\u0645 \u064a\u0646\u0628\u0626\u0643\u0645 \u0628\u0645\u0627 \u0643\u0627\u0646 \u0642\u0628\u0644\u0643\u0645 \u0648\u0645\u0627\u0647\u0648 \u0643\u0627\u0626\u0646 \u0628\u0639\u062f\u0643\u0645 \u0641\u0627\u0633\u062a\u0642\u064a\u0645\u0648\u0627 \u0648\u0633\u062f\u062f\u0648\u0627 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0644\u0627 \u064a\u0639\u0628\u0623 \u0628\u0639\u0630\u0627\u0628\u0643\u0645 \u0634\u064a\u0626\u0627\u064b \u0648\u0633\u064a\u0623\u062a\u064a \u0642\u0648\u0645 \u0644\u0627 \u064a\u062f\u0641\u0639\u0648\u0646 \u0639\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0634\u064a\u0626\u0627.",null)
B.b_c=new A.a("\u0648\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627: \u0625\u0646 \u0627\u0644\u0646\u0627\u0633 \u0646\u0632\u0644\u0648\u0627 \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0631\u0636 \u062b\u0645\u0648\u062f \u0627\u0644\u062d\u062c\u0631 \u0648\u0627\u0633\u062a\u0642\u0648\u0627 \u0645\u0646 \u0628\u0626\u0631\u0647\u0627 \u0648\u0627\u0639\u062a\u062c\u0646\u0648\u0627 \u0628\u0647\u060c \u0641\u0623\u0645\u0631\u0647\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u0647\u0631\u064a\u0642\u0648\u0627 \u0645\u0627 \u0627\u0633\u062a\u0642\u0648\u0627 \u0645\u0646 \u0628\u0626\u0627\u0631\u0647\u0627 \u0648\u0623\u0646 \u064a\u0639\u0644\u0641\u0648\u0627 \u0627\u0644\u0625\u0628\u0644 \u0627\u0644\u0639\u062c\u064a\u0646\u060c \u0648\u0623\u0645\u0631\u0647\u0645 \u0623\u0646 \u064a\u0633\u062a\u0642\u0648\u0627 \u0645\u0646 \u0627\u0644\u0628\u0626\u0631 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u0631\u062f\u0647\u0627 \u0627\u0644\u0646\u0627\u0642\u0629\u060c \u0648\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0644\u0627\u062a\u062f\u062e\u0644\u0648\u0627 \u0645\u0633\u0627\u0643\u0646 \u0627\u0644\u0630\u064a\u0646 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0625\u0644\u0627 \u0623\u0646 \u062a\u0643\u0648\u0646\u0648\u0627 \u0628\u0627\u0643\u064a\u0646 \u062d\u0630\u0631\u0627\u064b \u0623\u0646 \u064a\u0635\u064a\u0628\u0643\u0645 \u0645\u062b\u0644 \u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0645\u060c \u062b\u0645 \u0632\u062c\u0631 \u0641\u0623\u0633\u0631\u0639 \u062d\u062a\u0649 \u062e\u0644\u0641\u0647\u0627\u060c \u0648\u0647\u0630\u0627 \u0645\u0646\u0647\u062c \u0646\u0628\u0648\u064a \u0643\u0631\u064a\u0645 \u0641\u064a \u062a\u0648\u062c\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0635\u062d\u0627\u0628\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631 \u0628\u062f\u064a\u0627\u0631 \u062b\u0645\u0648\u062f \u0648\u0623\u0646 \u064a\u062a\u0630\u0643\u0631\u0648\u0627 \u0628\u0647\u0627 \u063a\u0636\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0623\u0646 \u0644\u0627\u064a\u063a\u0641\u0644\u0648\u0627 \u0639\u0646 \u0645\u0648\u0627\u0637\u0646 \u0627\u0644\u0639\u0638\u0629 \u0628\u0631\u0633\u0648\u0645\u0647\u0627 \u0627\u0644\u062f\u0627\u0631\u0633\u0629 \u0648\u0623\u0637\u0644\u0627\u0644\u0647\u0627 \u0627\u0644\u0642\u062f\u064a\u0645\u0629 \u0648\u0646\u0647\u0627\u0646\u0647\u0645 \u0639\u0646 \u0627\u0644\u0627\u0646\u062a\u0641\u0627\u0639 \u0628\u0634\u064a\u0621 \u0645\u0645\u0627 \u0641\u064a \u0631\u0628\u0648\u0639\u0647\u0627 \u062d\u062a\u0649 \u0627\u0644\u0645\u0627\u0621\u060c \u0644\u0643\u064a\u0644\u0627 \u062a\u0641\u0648\u062a \u0628\u0630\u0644\u0643 \u0627\u0644\u0639\u0628\u0631\u0629 \u0648\u062a\u062e\u0641 \u0627\u0644\u0645\u0648\u0639\u0638\u0629\u060c \u0628\u0644 \u0623\u0645\u0631\u0647\u0645 \u0628\u0627\u0644\u0628\u0643\u0627\u0621 \u0648\u0628\u0627\u0644\u062a\u0628\u0627\u0643\u064a \u062a\u062d\u0642\u064a\u0642\u0627\u064b \u0644\u0644\u062a\u0623\u062b\u0631 \u0628\u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0648 \u0623\u0646\u0647\u0645 \u0645\u0631\u0648\u0627 \u0628\u0647\u0627 \u0643\u0645\u0627 \u0646\u0645\u0631 \u0646\u062d\u0646 \u0628\u0622\u062b\u0627\u0631 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0644\u062a\u0639\u0631\u0636\u0648\u0627 \u0644\u0633\u062e\u0637 \u0627\u0644\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u063a\u0627\u0628\u0631\u064a\u0646 \u0634\u0647\u062f\u0648\u0627 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0648\u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u0646\u0628\u0648\u0627\u062a \u0648\u0639\u0627\u064a\u0646\u0648\u0627 \u0627\u0644\u0639\u062c\u0627\u0626\u0628 \u0644\u0643\u0646 \u0642\u0633\u062a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0641\u0627\u0633\u062a\u0647\u0627\u0646\u0648\u0627 \u0628\u0647\u0627 \u0648\u062d\u0642 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u062d\u0627\u0642 \u0628\u0647\u0645 \u0645\u0627\u0643\u0627\u0646\u0648\u0627 \u0628\u0647 \u064a\u0633\u062a\u0647\u0632\u0626\u0648\u0646 \u0645\u0646 \u0646\u0642\u0645\u0629 \u0627\u0644\u0644\u0647 \u0648\u063a\u0636\u0628\u0647.",null)
B.aWC=new A.a("\u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0645\u0627 \u0642\u0635 \u0639\u0644\u064a\u0646\u0627 \u0645\u0646 \u0623\u0646\u0628\u0627\u0621 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u062e\u0627\u0644\u064a\u0629 \u0625\u0644\u0627 \u0644\u0643\u064a \u0646\u0623\u062e\u0630\u0647\u0627 \u0645\u0646\u0647\u0627 \u0627\u0644\u0639\u0638\u0629 \u0648\u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631\u060c \u0641\u0625\u0630\u0627 \u0634\u0647\u062f\u0646\u0627 \u0628\u0623\u0639\u064a\u0646\u0646\u0627 \u062f\u064a\u0627\u0631\u0647\u0645 \u0627\u0644\u062a\u064a \u0646\u0632\u0644 \u0641\u064a\u0647\u0627 \u0633\u062e\u0637 \u0627\u0644\u0645\u0648\u0644\u0649 \u0639\u0632\u0648\u062c\u0644 \u0648\u0639\u0630\u0627\u0628\u0647 \u0627\u0644\u0623\u0644\u064a\u0645 \u0648\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0648\u0639\u0638\u0629 \u0623\u0634\u062f \u0648\u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631 \u0623\u0639\u0645\u0642 \u0648\u0627\u0644\u062e\u0648\u0641 \u0645\u0646 \u0633\u062e\u0637 \u0627\u0644\u0645\u0648\u0644\u0649 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0623\u0628\u0644\u063a\u060c \u0648\u0644\u0647\u0630\u0627 \u062a\u0633\u062c\u0649 \u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0648\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0633\u0644\u0627\u0645\u0647 \u0639\u0644\u064a\u0647 \u0628\u062b\u0648\u0628\u0647\u060c \u0644\u0645\u0627 \u0645\u0631 \u0628\u0627\u0644\u062f\u064a\u0627\u0631 \u0627\u0644\u0645\u0644\u0639\u0648\u0646\u0629 \u0627\u0644\u0645\u0633\u062e\u0648\u0637\u0629 \u0648\u0627\u0633\u062a\u062d\u062b \u062e\u0637\u0627 \u0631\u0627\u062d\u0644\u062a\u0647\u060c \u0648\u0642\u0627\u0644 \u0644\u0623\u0635\u062d\u0627\u0628\u0647: \u0644\u0627 \u062a\u062f\u062e\u0644\u0648\u0627 \u0628\u064a\u0648\u062a \u0627\u0644\u0630\u064a\u0646 \u0638\u0644\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0625\u0644\u0627 \u0648\u0623\u0646\u062a\u0645 \u0628\u0627\u0643\u0648\u0646 \u062e\u0648\u0641\u0627\u064b \u0623\u0646 \u064a\u0635\u064a\u0628\u0643\u0645 \u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0645.",null)
