B.aXZ=new A.a("\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: .. \u0641\u0644\u0645\u0627 \u0623\u0633\u0631\u0648\u0627 \u0627\u0644\u0623\u0633\u0627\u0631\u0649 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0623\u0628\u064a \u0628\u0643\u0631 \u0648\u0639\u0645\u0631: \u0645\u0627\u062a\u0631\u0648\u0646 \u0641\u064a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0633\u0627\u0631\u0649\u061f\u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631: \u064a\u0627\u0646\u0628\u064a \u0627\u0644\u0644\u0647 \u0647\u0645 \u0628\u0646\u0648 \u0627\u0644\u0639\u0645 \u0648\u0627\u0644\u0639\u0634\u064a\u0631\u0629: \u0623\u0631\u0649 \u0623\u0646 \u062a\u0623\u062e\u0630 \u0645\u0646\u0647\u0645 \u0641\u062f\u064a\u0629 \u0641\u062a\u0643\u0648\u0646 \u0644\u0646\u0627 \u0642\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u0639\u0633\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0647\u062f\u064a\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0645\u0627\u062a\u0631\u0649 \u064a\u0627 \u0627\u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628\u061f \u0642\u0627\u0644: \u0644\u0627\u0648\u0627\u0644\u0644\u0647 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u0627 \u0623\u0631\u0649 \u0627\u0644\u0630\u064a \u064a\u0631\u0627\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0648\u0644\u0643\u0646 \u0623\u0631\u0649 \u0623\u0646 \u062a\u0645\u0643\u0646\u0646\u0627 \u0645\u0646\u0647\u0645 \u0641\u0646\u0636\u0631\u0628 \u0623\u0639\u0646\u0627\u0642\u0647\u0645 \u0641\u062a\u0645\u0643\u0646 \u0639\u0644\u064a\u0627\u064b \u0645\u0646 \u0639\u0642\u064a\u0644 \u0641\u064a\u0636\u0631\u0628 \u0639\u0646\u0642\u0647 \u0648\u062a\u0645\u0643\u0646\u0646\u064a \u0645\u0646 \u0641\u0644\u0627\u0646 \u0646\u0633\u064a\u0628\u0627\u064b \u0644\u0639\u0645\u0631 \u0641\u0623\u0636\u0631\u0628 \u0639\u0646\u0642\u0647 \u0641\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0623\u0626\u0645\u0629 \u0627\u0644\u0643\u0641\u0631 \u0648\u0635\u0646\u0627\u062f\u064a\u062f\u0647\u0627 \u0641\u0647\u0648 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0627\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0648\u0644\u0645 \u064a\u0647\u0648 \u0645\u0627 \u0642\u0644\u062a: \u0641\u0644\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0627\u0644\u063a\u062f \u062c\u0626\u062a \u0641\u0625\u0630\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0642\u0627\u0639\u062f\u064a\u0646 \u064a\u0628\u0643\u064a\u0627\u0646 \u0642\u0644\u062a \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u062e\u0628\u0631\u0646\u064a \u0645\u0646 \u0623\u064a \u0634\u064a\u0621 \u062a\u0628\u0643\u064a \u0623\u0646\u062a \u0648\u0635\u0627\u062d\u0628\u0643 \u0641\u0625\u0646 \u0648\u062c\u062f\u062a \u0628\u0643\u0627\u0621 \u0628\u0643\u064a\u062a \u0648\u0625\u0646 \u0644\u0645 \u0623\u062c\u062f \u0628\u0643\u0627\u0621 \u062a\u0628\u0627\u0643\u064a\u062a \u0644\u0628\u0643\u0627\u0626\u0643\u0645\u0627\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u0628\u0643\u064a \u0644\u0644\u0630\u064a \u0639\u0631\u0636 \u0639\u0644\u064a\u0651 \u0623\u0635\u062d\u0627\u0628\u0643 \u0645\u0646 \u0623\u062e\u0630\u0647\u0645 \u0627\u0644\u0641\u062f\u0627\u0621 \u0648\u0644\u0642\u062f \u0639\u0631\u0636 \u0639\u0644\u064a\u0651 \u0639\u0630\u0627\u0628\u0647\u0645 \u0623\u062f\u0646\u0649 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0634\u062c\u0631\u0629 - \u0634\u062c\u0631\u0629 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644: \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0644\u0650\u0646\u064e\u0628\u0650\u064a\u0651\u064d \u0623\u064e\u0646\u0652 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u0633\u0652\u0631\u064e\u0649 \u062d\u064e\u062a\u0651\u064e\u0649 \u064a\u064f\u062b\u0652\u062e\u0650\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0623\u064e\u0631\u0652\u0636\u0650 - \u0625\u0644\u0649 \u0642\u0648\u0644\u0647: \u0641\u064e\u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0645\u0651\u064e\u0627 \u063a\u064e\u0646\u0650\u0645\u0652\u062a\u064f\u0645\u0652 \u062d\u064e\u0644\u0627\u0644\u0627 \u0637\u064e\u064a\u0651\u0650\u0628\u064b\u0627\u060c \u0641\u0623\u062d\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u0627\u0644\u063a\u0646\u064a\u0645\u0629.",null)
B.aYm=new A.a("\u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062a\u0636\u0639 \u0642\u0627\u0639\u062f\u0629 \u0647\u0627\u0645\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0627\u0644\u062f\u0648\u0644\u0629 \u062d\u064a\u0646\u0645\u0627 \u062a\u0643\u0648\u0646 \u0641\u064a \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0648\u0643\u064a\u0641 \u064a\u0646\u0628\u063a\u064a \u0623\u0644\u0627 \u062a\u0638\u0647\u0631 \u0628\u0645\u0638\u0647\u0631 \u0627\u0644\u0644\u064a\u0646 \u062d\u062a\u0649 \u062a\u0631\u0647\u0628 \u0645\u0646 \u0642\u0628\u0644 \u0623\u0639\u062f\u0627\u0626\u0647\u0627 \u0648\u0641\u064a \u0633\u0628\u064a\u0644 \u0647\u0630\u0647 \u0627\u0644\u0643\u0644\u064a\u0629 \u064a\u0637\u0631\u062d \u0627\u0644\u0627\u0647\u062a\u0645\u0627\u0645 \u0628\u0627\u0644\u062c\u0632\u0626\u064a\u0627\u062a \u062d\u062a\u0649 \u0648\u0644\u0648 \u0643\u0627\u0646\u062a \u0627\u0644\u062d\u0627\u062c\u0629 \u0645\u0644\u062d\u0629 \u0625\u0644\u064a\u0647\u0627 .",null)
B.aG8=new A.a("\u0643\u0627\u0646\u062a \u0645\u0639\u0627\u0645\u0644\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0644\u0623\u0633\u0631\u0649 \u062a\u062d\u0641\u0647\u0627 \u0627\u0644\u0631\u062d\u0645\u0629 \u0648\u0627\u0644\u0639\u062f\u0644 \u0648\u0627\u0644\u062d\u0632\u0645 \u0648\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062f\u0639\u0648\u064a\u0629 \u0648\u0644\u0630\u0644\u0643 \u062a\u0639\u062f\u062f\u062a \u0623\u0633\u0627\u0644\u064a\u0628\u0647 \u0648\u062a\u0646\u0648\u0639\u062a \u0637\u0631\u0642 \u062a\u0639\u0627\u0645\u0644\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u0647\u0646\u0627\u0643 \u0645\u0646 \u0642\u062a\u0644\u0647 \u0648\u0628\u0639\u0636\u0647\u0645 \u0642\u0628\u0644 \u0641\u064a\u0647\u0645 \u0627\u0644\u0641\u062f\u0627\u0621 \u0648\u0627\u0644\u0628\u0639\u0636 \u0627\u0644\u0622\u062e\u0631 \u0645\u0646\u0651 \u0639\u0644\u064a\u0647\u0645 \u0648\u0622\u062e\u0631\u0648\u0646 \u0627\u0634\u062a\u0631\u0637 \u0639\u0644\u064a\u0647\u0645 \u062a\u0639\u0644\u064a\u0645 \u0639\u0634\u0631\u0629 \u0645\u0646 \u0623\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0645\u0642\u0627\u0628\u0644 \u0627\u0644\u0645\u0646 \u0639\u0644\u064a\u0647\u0645.",null)
