B.b31=new A.a("\u062f\u0639\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0648\u0623\u0633\u0627\u0645\u0629 \u0628\u0646 \u0632\u064a\u062f \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u062d\u064a\u0646 \u0627\u0633\u062a\u0644\u0628\u062b - \u0627\u0644\u0625\u0628\u0637\u0627\u0621 \u0648\u0627\u0644\u062a\u0623\u062e\u0631 - \u0627\u0644\u0648\u062d\u064a \u064a\u0633\u062a\u0623\u0645\u0631\u0647\u0645\u0627 \u0641\u064a \u0641\u0631\u0627\u0642 \u0623\u0647\u0644\u0647\u060c \u0642\u0627\u0644\u062a \u0641\u0623\u0645\u0627 \u0623\u0633\u0627\u0645\u0629 \u0641\u0623\u0634\u0627\u0631 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u0645\u0646 \u0628\u0631\u0627\u0621\u0629 \u0623\u0647\u0644\u0647\u060c \u0648\u0628\u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0648\u062f \u0641\u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0647\u0644\u0643 \u0648\u0645\u0627\u0646\u0639\u0644\u0645 \u0625\u0644\u0627 \u062e\u064a\u0631\u0627\u064b\u060c \u0648\u0623\u0645\u0627 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0641\u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0644\u0645 \u064a\u0636\u064a\u0642 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643 \u0627\u0644\u0646\u0633\u0627\u0621 \u0633\u0648\u0627\u0647\u0627 \u0643\u062b\u064a\u0631 \u0648\u0625\u0646 \u062a\u0633\u0623\u0644 \u0627\u0644\u062c\u0627\u0631\u064a\u0629 \u062a\u0635\u062f\u0642\u0643. \u0642\u0627\u0644\u062a: \u0641\u062f\u0639\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0631\u064a\u0631\u0629 \u0641\u0642\u0627\u0644: \u0623\u064a \u0628\u0631\u064a\u0631\u0629 \u0647\u0644 \u0631\u0623\u064a\u062a \u0645\u0646 \u0634\u064a\u0621 \u064a\u0631\u064a\u0628\u0643\u061f \u0642\u0627\u0644\u062a \u0628\u0631\u064a\u0631\u0629: \u0644\u0627 \u0648\u0627\u0644\u0630\u064a \u0628\u0639\u062b\u0643 \u0628\u0627\u0644\u062d\u0642 \u0625\u0646 \u0631\u0623\u064a\u062a \u0639\u0644\u064a\u0647\u0627 \u0623\u0645\u0631\u0627\u064b \u0623\u063a\u0645\u0636\u0647 \u0639\u0644\u064a\u0647\u0627 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0623\u0646\u0647\u0627 \u062c\u0627\u0631\u064a\u0629 \u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u0633\u0646 \u062a\u0646\u0627\u0645 \u0639\u0646 \u0639\u062c\u064a\u0646 \u0623\u0647\u0644\u0647\u0627 \u0641\u062a\u0623\u062a\u064a \u0627\u0644\u062f\u0627\u062c\u0646 \u0641\u062a\u0623\u0643\u0644\u0647 \u0641\u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0641\u0627\u0633\u062a\u0639\u0630\u0631 \u064a\u0648\u0645\u0626\u0630 \u0645\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0628\u064a \u0628\u0646 \u0633\u0644\u0648\u0644 \u0642\u0627\u0644\u062a: \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0647\u0648 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0628\u0631: \u064a\u0627\u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0645\u0646 \u064a\u0639\u0630\u0631\u0646\u064a \u0645\u0646 \u0631\u062c\u0644 \u0642\u062f \u0628\u0644\u063a\u0646\u064a \u0623\u0630\u0627\u0647 \u0641\u064a \u0623\u0647\u0644 \u0628\u064a\u062a\u064a\u060c \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0639\u0644\u0645\u062a \u0639\u0644\u0649 \u0623\u0647\u0644\u064a \u0625\u0644\u0627 \u062e\u064a\u0631\u0627\u064b\u060c \u0648\u0644\u0642\u062f \u0630\u0643\u0631\u0648\u0627 \u0631\u062c\u0644\u0627\u064b \u0645\u0627\u0639\u0644\u0645\u062a \u0639\u0644\u064a\u0647 \u0625\u0644\u0627 \u062e\u064a\u0631\u0627\u064b\u060c \u0648\u0645\u0627\u0643\u0627\u0646 \u064a\u062f\u062e\u0644 \u0639\u0644\u0649 \u0623\u0647\u0644\u064a \u0625\u0644\u0627 \u0645\u0639\u064a\u060c \u0641\u0642\u0627\u0645 \u0633\u0639\u062f \u0628\u0646 \u0645\u0639\u0627\u0630 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u0641\u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0646\u0627 \u0623\u0639\u0630\u0631\u0643 \u0645\u0646\u0647 \u0625\u0646 \u0643\u0627\u0646 \u0645\u0646 \u0627\u0644\u0623\u0648\u0633 \u0636\u0631\u0628\u062a \u0639\u0646\u0642\u0647\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0645\u0646 \u0625\u062e\u0648\u0627\u0646\u0646\u0627 \u0645\u0646 \u0627\u0644\u062e\u0632\u0631\u062c \u0623\u0645\u0631\u062a\u0646\u0627 \u0641\u0641\u0639\u0644\u0646\u0627 \u0623\u0645\u0631\u0643.",null)
